// Parses FV-Lang token stream into an AST
// Security hardened with recursion depth limits

use crate::{lexer::Token, ast::*, CompileError};

// Security limits
const MAX_PARSE_DEPTH: usize = 1000;  // 최대 파싱 깊이
const MAX_TOKENS: usize = 100_000;    // 최대 토큰 수

pub struct Parser {
    tokens: Vec<Token>,
