// Fibonacci Example in FV-Lang
// Demonstrates recursive function definition and calls

fn fib(n: i32) -> i32 {
    if n <= 1 {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

fn main() -> i32 {
    // Calculate fibonacci(10) = 55
